local _, ns = ...
if ns.LOCALE ~= "frFR" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/frFR.lua.
L["WN99_1_TITLE"] = "Partager une quête"
L["WN99_1_TEXT"] = "Le partage de quêtes depuis le journal de quêtes fonctionne de nouveau avec votre groupe."
L["WN99_2_TITLE"] = "Menus déroulants des Options"
L["WN99_2_TEXT"] = "Les menus déroulants des Options du jeu n'affichent plus de bouton étiré à l'intérieur avec un thème personnalisé texturé."
L["WN99_3_TITLE"] = "En combat"
L["WN99_3_TEXT"] = "En combat, les barres d'action ne sautent plus quand une fenêtre s'ouvre alors qu'un bouton du micro-menu est masqué, le livre des métiers ouvert depuis le grimoire reste à la place du grimoire sans second volet vide, et inspecter les talents d'un joueur depuis son menu n'ouvre plus que notre fenêtre, sans erreur."
L["WN99_4_TITLE"] = "Discussion"
L["WN99_4_TEXT"] = "La discussion et ses onglets ne disparaissent plus quand un autre addon redimensionne la discussion."
L["WN99_5_TITLE"] = "Menus déroulants et What's Training"
L["WN99_5_TEXT"] = "Avec un thème personnalisé texturé, les menus déroulants de nos options sont de nouveau dessinés en entier, et What's Training dans le livre des métiers prend le marbre noir du grimoire sans lignes sur la liste."
L["WN98_1_TITLE"] = "Icônes de sac sur les emplacements vides"
L["WN98_1_TEXT"] = "Dans Un seul sac, chaque emplacement vide montre désormais une icône pâle du sac auquel il appartient, pour repérer d'un coup d'oeil les emplacements d'un carquois. Activez-la dans les options (/fcui) : Un seul sac, sous Sacs. Emplacements vides unis, juste en dessous, les rend de nouveau tous pareils."
L["WN98_2_TITLE"] = "Couleurs de classe en champ de bataille"
L["WN98_2_TEXT"] = "Les barres de nom des joueurs ennemis montrent désormais leur couleur de classe en champ de bataille et en donjon, où le jeu cache leur classe et où elles étaient rouges."
L["WN98_3_TITLE"] = "Les sacs restent en place"
L["WN98_3_TEXT"] = "Les sacs déplacés en mode Édition restent désormais là où vous les laissez. Ceux placés avant cette version restent où ils sont."
L["WN98_4_TITLE"] = "Fenêtres au premier plan"
L["WN98_4_TEXT"] = "Une fenêtre glissée sur le journal de quêtes ou le grimoire passe désormais par-dessus, et les icônes du grimoire ne transparaissent plus."
L["WN98_5_TITLE"] = "Onglets de la recherche de groupe"
L["WN98_5_TEXT"] = "La recherche de groupe et une fenêtre qu'un autre addon ouvre depuis ses onglets latéraux partagent désormais une même place : changer d'onglet ne fait plus sauter la fenêtre, et déplacer l'une déplace les deux."
L["WN97_1_TITLE"] = "Plus d'espace au niveau maximum"
L["WN97_1_TEXT"] = "Au niveau maximum, sans barre d'expérience ni de réputation, les barres au-dessus de la barre principale reposent maintenant sur la fine barre où se trouvait l'expérience, comme dans Era."
L["WN97_2_TITLE"] = "Défis d'Héritage"
L["WN97_2_TEXT"] = "La liste des Défis range ses sections comme la fenêtre du jeu, et sa recherche trouve tout mot qu'un défi affiche, de ses sections à ses étapes."
L["WN97_3_TITLE"] = "Onglets latéraux d'autres addons"
L["WN97_3_TEXT"] = "Les onglets latéraux que d'autres addons ajoutent à la recherche de groupe, comme celui de LFG Forever, ressemblent maintenant aux nôtres et s'alignent dessous."
L["WN96_1_TITLE"] = "Jets de butin d'Era"
L["WN96_1_TEXT"] = "/loot ouvre la fenêtre des jets de butin d'Era : chaque objet avec son gagnant et son jet, et + sur un objet affiche tous les jets. Faites glisser l'onglet du dessous pour la hauteur, ou son coin pour les deux sens."
L["WN96_2_TITLE"] = "Apparaître hors ligne"
L["WN96_2_TEXT"] = "Le menu de statut de la fenêtre sociale classique propose désormais d'apparaître hors ligne, à côté de Disponible, Absent et Occupé."
L["WN96_3_TITLE"] = "Social décoché"
L["WN96_3_TEXT"] = "Décocher Social sur la page Toutes les fenêtres vous donne désormais la fenêtre sociale du jeu, sans aucun de nos onglets."
L["WN95_1_TITLE"] = "Un seul sac par profil"
L["WN95_1_TEXT"] = "Les profils retiennent désormais l'option Un seul sac : les personnages sur des profils différents gardent leur propre mode de sacs. Avant, un changement sur un personnage s'appliquait à tous. Activez-la dans les options (/fcui) sur chaque profil qui la veut : Un seul sac, sous Sacs."
L["WN95_2_TITLE"] = "Caractéristiques en combat"
L["WN95_2_TEXT"] = "Les caractéristiques de la fenêtre du personnage ne sont plus vides à sa première ouverture en combat, et les attributs, la vie, l'armure, le critique, la hâte et l'esquive suivent les améliorations pendant le combat."
L["WN94_1_TITLE"] = "Distribution du butin"
L["WN94_1_TEXT"] = "La distribution du butin au groupe fonctionne de nouveau avec la fenêtre de butin classique : un clic sur un objet affiche la liste des joueurs, à la manière d'Era sous l'objet."
L["WN93_1_TITLE"] = "Styles des barres de nom"
L["WN93_1_TEXT"] = "Classique figure désormais dans la liste des styles des barres de nom du jeu (Options, Barres de nom). Choisir l'un des styles du jeu désactive nos barres de nom pour afficher ce style ; Classique ramène les nôtres."
L["WN93_2_TITLE"] = "Historique du butin"
L["WN93_2_TEXT"] = "La fenêtre d'historique du butin (/loot) porte l'ancien cadre avec votre thème. Faites glisser son coin pour la redimensionner dans les deux sens ; un clic droit sur le coin lui rend sa propre taille."
L["WN93_3_TITLE"] = "Fond de la barre de posture"
L["WN93_3_TEXT"] = "Le fond derrière les barres de posture et de familier suit le thème des barres d'action, comme l'art de la barre elle-même."
L["WN93_4_TITLE"] = "Quantité des métiers"
L["WN93_4_TEXT"] = "Cliquer dans la case de quantité de la fenêtre de métier classique sélectionne le nombre, si bien que la saisie le remplace, comme dans Era."
L["WN92_1_TITLE"] = "Barres de posture et de familier"
L["WN92_1_TEXT"] = "Les barres de posture, de familier et de possession se placent là où Era les met : au-dessus de la barre principale sur le fond d'Era, ou juste au-dessus de la barre 2 quand elle est affichée. Faites-en glisser une en mode Édition pour la placer vous-même."
L["WN92_2_TITLE"] = "Barre des totems"
L["WN92_2_TEXT"] = "La barre des totems du chaman se place à l'emplacement de la barre de posture, au-dessus de la barre principale, et y reste après chaque chargement."
L["WN92_3_TITLE"] = "Barres d'action"
L["WN92_3_TEXT"] = "Désactiver la barre 2 ou la barre 3 laisse l'autre là où elle était."
L["WN92_4_TITLE"] = "Macros de métier"
L["WN92_4_TEXT"] = "Une macro peut appuyer sur Créer dans la fenêtre de métier classique, comme une macro d'enchantement rapide : /run ClassicUIForeverTradeSkill.CreateButton:Click()"
L["WN91_1_TITLE"] = "Suivi des quêtes"
L["WN91_1_TEXT"] = "Des quêtes retirées du suivi y reviennent ? C'est le suivi automatique des quêtes du jeu. Décochez Suivi automatique des quêtes sous Quêtes (/fcui) et elles n'y reviennent plus."
L["WN91_2_TITLE"] = "Panneau de raid"
L["WN91_2_TEXT"] = "Le panneau de groupe au bord gauche de l'écran peut rester caché jusqu'à ce que la souris passe dessus. Activez-le dans les options (/fcui) : Panneau de raid au survol, sous Cadres d'unité."
L["WN90_1_TITLE"] = "Couleurs des quêtes"
L["WN90_1_TEXT"] = "Toutes vos quêtes en jaune ? C'est le réglage du jeu des couleurs de difficulté des quêtes, désactivé. Il est désormais aussi dans les options (/fcui) : cochez Couleurs de difficulté des quêtes sous Quêtes."
L["WN90_2_TITLE"] = "Onglet familier"
L["WN90_2_TEXT"] = "Il affiche les caractéristiques qu'ont vraiment les familiers : points de vie, vitesse, chances de coup critique, hâte, puissance d'attaque, dégâts, défense et armure."
L["WN90_3_TITLE"] = "Sacs"
L["WN90_3_TEXT"] = "Les sacs déposés sur la barre classique en mode édition y restent après une reconnexion, et une erreur Lua que certains addons provoquaient en rafraîchissant les sacs a disparu."
L["WN90_4_TITLE"] = "Collections"
L["WN90_4_TEXT"] = "Dans Apparences, l'aperçu cadre tout votre personnage, et essayer une autre apparence du même emplacement garde la caméra là où vous l'aviez laissée."
L["WN90_5_TITLE"] = "Journal de quêtes"
L["WN90_5_TEXT"] = "Il ne ralentit plus pendant qu'un autre addon charge des données d'objets."
L["WN89_1_TITLE"] = "Plus de boîte de haut fait"
L["WN89_1_TEXT"] = "La boîte du jeu qui surgit quand vous accomplissez un haut fait (sur Forever, un défi d'Héritage) ou l'une de ses étapes a disparu, car 1.x n'en avait pas. Pour la retrouver, activez-la dans les options (/fcui) : cochez Avis de haut fait sous Autre."
L["WN89_2_TITLE"] = "Onglet Compétences"
L["WN89_2_TEXT"] = "Son volet inférieur ne reste plus affiché quand la fenêtre du personnage s'ouvre sur un autre onglet."
L["WN88_1_TITLE"] = "Familiers"
L["WN88_1_TEXT"] = "Invoquer un autre familier ne fige plus le jeu un instant."
L["WN88_2_TITLE"] = "Journal de quêtes"
L["WN88_2_TEXT"] = "Le son d'abandon d'une quête ne se joue que lorsque vous choisissez Oui."
L["WN88_3_TITLE"] = "Métiers"
L["WN88_3_TEXT"] = "Le livre des métiers compte l'équipement, comme une canne à pêche, dans le bonus de chaque compétence."
L["WN87_1_TITLE"] = "Infobulles d'unité"
L["WN87_1_TEXT"] = "La ligne qui invite au clic droit pour les options du cadre n'apparaît plus dans les infobulles des cadres d'unité, comme dans Era. Pour la revoir, désactivez Masquer l'indication du clic droit dans les options (/fcui), sous Cadres d'unité."
L["WN87_2_TITLE"] = "Sacs"
L["WN87_2_TEXT"] = "Le sac à dos garde son image classique quand les sacs changent."
L["WN87_3_TITLE"] = "Fenêtre du personnage"
L["WN87_3_TEXT"] = "Les lignes de chances de toucher affichent de nouveau leur infobulle."
L["WN87_4_TITLE"] = "Marchands"
L["WN87_4_TEXT"] = "Les boutons de réparation affichent les icônes d'Era."
L["WN87_5_TITLE"] = "Barre d'expérience"
L["WN87_5_TEXT"] = "La barre d'expérience est placée comme dans Era et aussi haute."
L["WN86_1_TITLE"] = "Addons de barres d'action"
L["WN86_1_TEXT"] = "Avec un addon de barres d'action qui remplace les barres du jeu, ses barres gardent leurs boutons et leur apparence, skins de Masque compris, et Déconnexion et Quitter le jeu du menu du jeu fonctionnent de nouveau."
L["WN86_2_TITLE"] = "Barre classique désactivée"
L["WN86_2_TEXT"] = "Les boutons de familier et de posture et le bouton du personnage retrouvent leur propre apparence."
L["WN85_1_TITLE"] = "Fenêtre des options du jeu"
L["WN85_1_TEXT"] = "La fenêtre des options du jeu ne fait plus baisser la fréquence d'images tant qu'elle est ouverte."
L["WN85_2_TITLE"] = "Talents"
L["WN85_2_TEXT"] = "Un talent bloqué tant que son arbre n'a pas assez de points indique en rouge combien il en faut, comme dans Era."
L["WN85_3_TITLE"] = "Barre d'expérience"
L["WN85_3_TEXT"] = "Les traits de segment du jeu ne s'affichent plus sur la barre d'expérience après une connexion en combat."
L["WN85_4_TITLE"] = "Métiers"
L["WN85_4_TEXT"] = "Le livre des métiers garde ensemble les sorts de chaque métier quand il est ouvert en combat, et avec TradeSkillMaster la fenêtre des métiers ne saute plus vers la droite à la fin d'un combat."
L["WN84_1_TITLE"] = "Fenêtres de marchand et de maître"
L["WN84_1_TEXT"] = "Les fenêtres des marchands et des maîtres peuvent maintenant être déplacées et redimensionnées. Cliquez sur le cadenas à côté du bouton de fermeture, puis faites glisser la fenêtre ou son coin. Elles partagent un même emplacement et une même taille avec les fenêtres de quête et de dialogue, et dans les fenêtres ClassicUI Forever (mode Édition), les fenêtres qui partagent un emplacement n'ont qu'une ligne et un cadre."
L["WN84_2_TITLE"] = "Suivi et réglages de quêtes de la carte"
L["WN84_2_TEXT"] = "Les titres des quêtes dans le suivi classique, le journal de quêtes et les listes de quêtes de la carte suivent le réglage de la carte Couleur de quête par difficulté (unis quand il est désactivé), et ce réglage ainsi que Afficher le niveau des quêtes s'appliquent aussitôt, sans rechargement."
L["WN84_3_TITLE"] = "Corrections"
L["WN84_3_TEXT"] = "Le titre d'une quête dans le suivi classique garde sa couleur quand la souris le quitte, les barres de défilement de la carte classique combinée tiennent à leur place quand la carte est en fenêtre, la touche de la carte ferme cette carte sur tous les personnages, et le bouton de la minicarte reste dans le sac de MinimapButtonBag Reborn."
L["WN84_4_TITLE"] = "Onglet Compétences"
L["WN84_4_TEXT"] = "Une compétence qui augmente en combat ne provoque plus d'erreur quand l'onglet Compétences affiche une compétence d'arme."
L["WN83_1_TITLE"] = "Compétences et hôtel des ventes"
L["WN83_1_TEXT"] = "L'onglet Compétences ne provoque plus d'erreur pour un personnage avec un bonus de Défense, et le bouton d'enchère de l'hôtel des ventes ne recouvre plus la fin de la case du cuivre."
L["WN83_2_TITLE"] = "Panneau de raid et manette"
L["WN83_2_TEXT"] = "L'onglet fermé du panneau de raid reste au bord de l'écran quand vous rejoignez un groupe en combat, et les options de manette affichent les icônes Vue et Menu de votre manette."
L["WN82_1_TITLE"] = "Partager la quête avec la carte en plein écran"
L["WN82_1_TEXT"] = "Partager une quête depuis le journal de quêtes ne laisse plus la carte du monde ouverte quand vous utilisez la carte en plein écran."
L["WN82_2_TITLE"] = "Partager la quête"
L["WN82_2_TEXT"] = "Partager la quête dans le journal de quêtes partage la quête, au lieu de dire de la partager depuis la carte du monde."
L["WN81_1_TITLE"] = "Coût de fabrication et profit"
L["WN81_1_TEXT"] = "Avec Auctionator, la fenêtre de métier classique affiche au-dessus des composants ce que coûte une recette et son profit, et un bouton Rechercher pour les composants quand l'hôtel des ventes est ouvert."
L["WN81_2_TITLE"] = "Couleurs de classe pour alliés ou ennemis"
L["WN81_2_TEXT"] = "Joueurs alliés et Joueurs ennemis sont des cases séparées sous les couleurs de classe des barres de nom, la case du nom en couleur de classe et la vie en couleur de classe : elles peuvent ne valoir que pour un camp. Les options de couleur de classe sont désactivées par défaut : activez-les dans les options (/fcui)."
L["WN81_3_TITLE"] = "Course automatique à la manette"
L["WN81_3_TEXT"] = "Sur la disposition classique, la course automatique est par défaut sur l'appui du stick gauche, et un bouton choisi pour la course automatique ou la discussion marche aussi sur un stick avec lequel le curseur clique."
L["WN81_4_TITLE"] = "Corrections"
L["WN81_4_TEXT"] = "La liste de What's Training dans la fenêtre de métier à deux volets repose sur un seul fond, et les barres de vie et de focalisation du cadre du familier remplissent leurs emplacements."
L["WN80_1_TITLE"] = "Manette sur la disposition classique (en cours)"
L["WN80_1_TEXT"] = "Jouez avec les barres classiques à la manette pendant que l'interface manette du jeu est désactivée : la croix directionnelle et les boutons de façade lancent la barre d'action 1, ou les autres barres avec une gâchette maintenue. Désactivé par défaut ; une fenêtre le demande à la première utilisation d'une manette, et l'option se trouve dans les options (/fcui), sous Manette. Encore en cours : les sacs, la carte et les menus demandent pour l'instant le curseur du jeu."
L["WN80_2_TITLE"] = "Panneau de raid en combat"
L["WN80_2_TEXT"] = "Le panneau de raid et de groupe garde ses lignes en place quand le groupe change pendant un combat, et son onglet ne disparaît plus quand vous fermez le panneau en combat."
L["WN80_3_TITLE"] = "Dressage du familier"
L["WN80_3_TEXT"] = "La fenêtre de l'instructeur ne garde plus une ancienne liste : les compétences que votre familier connaît déjà ne restent plus affichées comme à apprendre."
L["WN79_1_TITLE"] = "Panneau de raid en combat"
L["WN79_1_TEXT"] = "Le panneau de raid et de groupe ne provoque plus d'erreur quand votre groupe change pendant un combat, par exemple quand un membre monte de niveau. Il se met à jour à la fin du combat."
L["WN78_1_TITLE"] = "Panneau de raid classique"
L["WN78_1_TEXT"] = "Le panneau de raid et de groupe au bord gauche de l'écran a l'aspect et l'ordre classiques, et toutes les commandes du jeu y sont toujours. Son bouton de marqueurs au sol fait marquer le sol aux icônes de cible."
L["WN78_2_TITLE"] = "Bord du panneau de raid"
L["WN78_2_TEXT"] = "Fermé, le panneau ne montre que son onglet fléché. Bord du panneau de raid une fois fermé garde son cadre au bord de l'écran, comme dans Era. Désactivé par défaut ; activez-le dans les options (/fcui), sous Cadres d'unité."
L["WN78_3_TITLE"] = "Petites corrections"
L["WN78_3_TEXT"] = "La fenêtre de butin s'ouvre aussitôt et ne saute plus quand vous cliquez sur un objet avec les sacs pleins. Les boutons de l'onglet de guilde et de la fenêtre des communautés ne restent plus cliquables après la fermeture de leur fenêtre en combat."
L["WN77_1_TITLE"] = "Recherche chez le maître"
L["WN77_1_TEXT"] = "La fenêtre d'un maître a un champ de recherche à côté de son filtre. Il ne montre que les sorts et recettes dont le nom contient les mots. Champ de recherche, sous Fenêtre de maître dans les options (/fcui), le désactive."
L["WN77_2_TITLE"] = "What's Training dans sa propre fenêtre"
L["WN77_2_TEXT"] = "L'onglet de formation du grimoire peut ouvrir la fenêtre de What's Training au lieu d'une page du livre ; la fenêtre se ferme avec le livre. Désactivé par défaut ; activez-le dans les options (/fcui), sous Grimoire."
L["WN77_3_TITLE"] = "Noms de guilde en couleur de classe"
L["WN77_3_TEXT"] = "Les noms de la liste de guilde peuvent s'afficher dans leur couleur de classe. Désactivé par défaut ; activez-le dans les options (/fcui), sous Liste de guilde."
L["WN77_4_TITLE"] = "Banque classique"
L["WN77_4_TEXT"] = "La banque a les plaques d'emplacement et les rivets classiques, avec leur espacement classique, dans une fenêtre plus courte."
L["WN77_5_TITLE"] = "Champs de recherche"
L["WN77_5_TEXT"] = "Les champs de recherche du journal de quêtes et des métiers ont l'aspect de saisie classique."
L["WN77_6_TITLE"] = "Avis au-dessus de la discussion"
L["WN77_6_TEXT"] = "Les notifications d'amis et l'avis d'actualisation du monde se placent au-dessus des onglets de la discussion. Sur une fenêtre de discussion plus haute, ils couvraient son texte et ses onglets."
L["WN77_7_TITLE"] = "Petites corrections"
L["WN77_7_TEXT"] = "Forever Quest Tint couvre toute la page de quête de la carte, et non une bande sous le titre. Fermer une banque ou un marchand ne décale plus un instant les sacs ouverts, et /fstack ne liste plus les cadres d'aide cachés de l'addon."
L["WN76_1_TITLE"] = "Recherche dans le journal de quêtes"
L["WN76_1_TEXT"] = "Le journal de quêtes à double volet a un champ de recherche dans son en-tête. Il liste les quêtes dont le nom ou la zone contient les mots."
L["WN76_2_TITLE"] = "Trier par difficulté"
L["WN76_2_TEXT"] = "Toutes les recettes d'un métier en une seule liste, orange d'abord, puis jaune, vert et gris. Activez-le dans le menu Filtre de la fenêtre d'un métier ou dans les options (/fcui), sous Métiers."
L["WN76_3_TITLE"] = "Boutons de fermeture classiques"
L["WN76_3_TEXT"] = "La banque de guilde et la carte du maître de vol ont le X classique."
L["WN75_1_TITLE"] = "Infobulle d'un lien d'objet"
L["WN75_1_TEXT"] = "Le X de l'infobulle d'un lien d'objet est le classique, à sa place classique."
L["WN75_2_TITLE"] = "Techniques de familier sur le curseur"
L["WN75_2_TEXT"] = "Après un changement de familier, une technique de familier dont le jeu ne garde pas la copie est placée une fois, et non encore et encore. Avec certains familiers, cela mettait des icônes sur le curseur et ralentissait le jeu."
L["WN74_1_TITLE"] = "Page d'entraînement du grimoire"
L["WN74_1_TEXT"] = "La page d'entraînement du grimoire fonctionne avec What's Training 11.3. Avec cette version, l'onglet ouvrait la propre fenêtre de What's Training au lieu de la liste dans le grimoire."
L["WN74_2_TITLE"] = "Partager une quête depuis le journal"
L["WN74_2_TEXT"] = "Partager une quête dans le journal des quêtes partage aussi les quêtes hors de la zone où vous êtes, donjons compris, et laisse la carte du monde fermée ensuite."
L["WN73_1_TITLE"] = "Formation dans la fenêtre d'un métier"
L["WN73_1_TEXT"] = "Avec What's Training installé, la fenêtre d'un métier a deux onglets latéraux : celui du bas liste ce que son maître peut vous apprendre, celui du haut revient au métier. Les onglets de formation portent les icônes de What's Training, dans le grimoire aussi."
L["WN73_2_TITLE"] = "Butin en combat"
L["WN73_2_TEXT"] = "Fouiller un cadavre en combat ouvre la fenêtre de butin. Dès le deuxième butin d'une session, le jeu la refusait avec le message qu'une action de l'interface a échoué à cause d'un addon."
L["WN73_3_TITLE"] = "Grimoire"
L["WN73_3_TEXT"] = "Le bouton du micromenu et la touche ferment le livre depuis la page What's Training, et un livre fermé là se rouvre. En combat le livre s'ouvre au début de la rangée de fenêtres ; il s'ouvrait loin à droite quand la carte était ouverte au début du combat."
L["WN73_4_TITLE"] = "Taille des plaques par personnage"
L["WN73_4_TEXT"] = "Même taille de près et de loin applique le choix de chaque personnage à la connexion. Il ne prenait effet qu'après avoir changé la case sur ce personnage. Activez-la dans les options (/fcui), sous Plaques de nom."
L["WN72_1_TITLE"] = "Cabine d'essayage"
L["WN72_1_TEXT"] = "La cabine d'essayage s'ouvre à la taille de 1.x. Pour la cabine plus grande des clients ultérieurs, activez Grande cabine d'essayage dans les options (/fcui), sous Toutes les fenêtres ; nos fenêtres lui laissent la place à côté pour ses panneaux latéraux."
L["WN72_2_TITLE"] = "Fondu du micromenu"
L["WN72_2_TEXT"] = "Le micromenu peut s'estomper comme les barres d'action : réglez Opacité estompée ou Afficher seulement au survol dans sa fenêtre du mode d'édition, et liez-le aux barres estompées."
L["WN72_3_TITLE"] = "Fenêtre de guilde"
L["WN72_3_TEXT"] = "Ajouter un membre, Informations de guilde et le menu du clic droit sur un membre passent par les boutons et le menu du jeu lui-même, donc inviter, modifier les informations, renvoyer, promouvoir et rétrograder fonctionnent."
L["WN72_4_TITLE"] = "Onglet latéral Qui"
L["WN72_4_TEXT"] = "L'onglet latéral Qui de la recherche de groupe est masqué pour tous. Désactivez Masquer l'onglet latéral Qui dans les options (/fcui), sous Social, pour le retrouver."
L["WN72_5_TITLE"] = "Taille des plaques de nom"
L["WN72_5_TEXT"] = "Même taille de près et de loin garde les plaques à une seule taille comme dans Classic Era, désormais via les réglages du jeu et gardée par personnage, hors profils. Activez-la dans les options (/fcui), sous Plaques de nom."
L["WN72_6_TITLE"] = "Corrections"
L["WN72_6_TEXT"] = "Un long nom de guilde se termine par des points avant la colonne de zone, la fenêtre du maître fait défiler une longue description, Ctrl-clic sur une récompense de quête ouvre la cabine d'essayage, les boutons de la barre de totems portent l'aspect classique, le nombre du groupe d'une quête reste sans les niveaux de quête, et les listes de What's Training tiennent sur une page du grimoire avec un onglet Métiers à côté."
L["WN71_1_TITLE"] = "La barre de totems reste en place"
L["WN71_1_TEXT"] = "Une barre accrochée à une barre d'action en mode édition, comme la barre de totems du chaman, garde sa place à la fermeture du mode édition et après un rechargement."
L["WN71_2_TITLE"] = "Barres de boutons de la minicarte"
L["WN71_2_TEXT"] = "Une barre de boutons de la minicarte d'un autre addon peut de nouveau être déplacée avec ClassicUI Forever."
L["WN71_3_TITLE"] = "Pourcentage de menace"
L["WN71_3_TEXT"] = "Le pourcentage de menace sur la cible et la focalisation s'arrête à 999 %, comme dans Classic Era."
L["WN70_1_TITLE"] = "Estompage lié"
L["WN70_1_TEXT"] = "Les barres d'action estompées peuvent revenir ensemble : cochez Liée aux autres barres estompées sur les barres estompées, en mode édition, et la souris sur l'une d'elles les affiche toutes (#255)."
L["WN70_2_TITLE"] = "Lueur d'enchantement"
L["WN70_2_TEXT"] = "La lueur dorée du jeu après une pierre à aiguiser, une huile ou un enchantement est désactivée, car Classic Era n'en avait pas. Pour la retrouver, activez-la dans les options (/fcui) : Lueur dorée à l'enchantement sous Fiche de personnage. Elle suit désormais le bord de la fenêtre (#262)."
L["WN70_4_TITLE"] = "Onglet des titres"
L["WN70_4_TEXT"] = "Le panneau latéral de la fenêtre du personnage retrouve l'onglet Titres (#261). Les icônes de talents remplissent leurs cases comme dans Classic Era (#260)."
L["WN70_3_TITLE"] = "Fenêtre de butin à la manette"
L["WN70_3_TEXT"] = "À la manette, la croix directionnelle parcourt les objets de la fenêtre de butin (#264)."
L["WN69_1_TITLE"] = "Nos fenêtres à la manette"
L["WN69_1_TEXT"] = "Avec l'interface manette active, le grimoire classique, les talents, le journal de quêtes, les collections, la fenêtre Legacy et le sac unique fonctionnent à la manette : la croix directionnelle déplace, A sélectionne, B ferme, et les boutons à presser s'affichent sous la fenêtre. Le grimoire et les talents s'ouvrent de nouveau dans leurs propres fenêtres. Dans le journal de quêtes la liste défile au fil des déplacements, et Y ouvre la carte."
L["WN69_2_TITLE"] = "Assigner des sorts depuis le grimoire"
L["WN69_2_TEXT"] = "À la manette, appuyez sur X sur un sort du grimoire classique, puis sur le bouton voulu ; maintenez LT ou RT pour les groupes latéraux, comme dans le grimoire du jeu. Y ouvre l'éditeur de barres d'action du jeu."
L["WN69_3_TITLE"] = "Onglets de métier masqués"
L["WN69_3_TEXT"] = "Les onglets à côté de la fenêtre des métiers sont masqués, car Classic Era n'en avait pas. Pour les retrouver, activez-les dans les options (/fcui) : choisissez Onglets de métier : au survol ou toujours visibles sous Livre des métiers. La liste des recettes à apprendre de What's Training s'ouvre depuis un onglet à côté du livre (#260)."
L["WN69_4_TITLE"] = "Changements mineurs"
L["WN69_4_TEXT"] = "La fenêtre de discussion garde sa place quand un autre addon la redimensionne par son bord supérieur (#247). À la manette, les onglets Grimoire et Collections de la fenêtre des métiers tournent la page sur place, et le contour de la fenêtre du personnage épouse son cadre."
L["WN68_1_TITLE"] = "Onglets de double spécialisation sur la fenêtre des talents"
L["WN68_1_TEXT"] = "Les onglets des deux spécialisations descendent le long du bord de la fenêtre des talents, comme dans Classic. Cliquez sur l'un d'eux pour voir cette spécialisation."
L["WN68_2_TITLE"] = "Le texte de la carte du monde à la taille du jeu"
L["WN68_2_TEXT"] = "Dans le style Classic de l'en-tête, l'en-tête, le volet des quêtes et les Options de la carte s'affichaient à 70 % de la taille du texte du jeu en fenêtre. Ils sont maintenant à la taille du jeu, le volet des quêtes a sa pleine largeur, et les libellés Continent et Zone sont à côté de leurs menus déroulants."
L["WN68_3_TITLE"] = "Les quêtes sur parchemin dans le volet de la carte"
L["WN68_3_TEXT"] = "Le volet des quêtes de la carte liste les quêtes sur le parchemin du jeu. Pour la pierre sombre, décochez Liste sur le parchemin du jeu sous Carte du monde."
L["WN68_4_TITLE"] = "Boutons d'addons laissés sur l'anneau"
L["WN68_4_TEXT"] = "Avec Regrouper les boutons d'addons activé, Laisser sur l'anneau liste chaque bouton d'addon ; cochez ceux qui restent sur l'anneau pendant que les autres vont dans le sac. Regrouper les boutons d'addons est désactivé par défaut ; activez-le dans les options (/fcui), sous Minicarte."
L["WN68_5_TITLE"] = "Plus de boîte Nouvelle recette apprise"
L["WN68_5_TEXT"] = "La boîte du jeu qui surgit quand un métier vous enseigne quelque chose a disparu, car 1.x n'en avait pas. Pour la retrouver, activez-la dans les options (/fcui) : cochez Avis de compétence sous Autre."
L["WN68_6_TITLE"] = "Changements mineurs"
L["WN68_6_TEXT"] = "Un talent sous son rang maximal est vert, que vous ayez des points à dépenser ou non, comme dans Classic Era. Les listes de la fenêtre sociale comptent leurs lignes entières (#232), et la ligne Chiffres de dégâts a disparu, car elle ne faisait que refléter le réglage du jeu lui-même."
L["WN67_1_TITLE"] = "Les éléments de la minicarte y restent"
L["WN67_1_TEXT"] = "Chaque élément de la minicarte dans ClassicUI Forever Windows a une case Rester sur la minicarte. Cochée, l'élément garde sa place sur la minicarte. Décochez-la pour le déplacer où vous voulez."
L["WN67_2_TITLE"] = "La fenêtre Options suit le thème"
L["WN67_2_TEXT"] = "Sa bordure et les éléments de Classic Era portent le look sombre, bronze ou personnalisé, et le look classique ne laisse plus de bronze sur ses bords."
L["WN67_3_TITLE"] = "Les cases et l'en-tête du sac unique"
L["WN67_3_TEXT"] = "Les cases vides n'affichent pas d'icône de sac, la recherche va jusqu'au bouton Ranger, et la bande d'en-tête est entière."
L["WN67_4_TITLE"] = "La carte du monde en combat"
L["WN67_4_TEXT"] = "Ouverte en combat, la carte est dimensionnée par l'addon seul, si bien qu'un autre addon de carte ne peut plus déclencher d'erreur d'action bloquée."
L["WN66_1_TITLE"] = "Les infobulles retrouvent le fond sombre de Classic Era"
L["WN66_1_TEXT"] = "Chaque infobulle porte le fond sombre d'Era dans tous les styles. Le fond plus clair et plus bleu du jeu transparaissait dès la deuxième infobulle, avec un jour le long du bord."
L["WN66_2_TITLE"] = "La minicarte se déplace de nouveau en mode Édition"
L["WN66_2_TEXT"] = "Glissée en mode Édition, la minicarte reste visible et sa nouvelle place est enregistrée."
L["WN66_3_TITLE"] = "La carte du monde garde sa taille en combat"
L["WN66_3_TEXT"] = "Ouverte en combat, la carte a la même taille qu'en dehors, avec ou sans le journal des quêtes."
L["WN65_1_TITLE"] = "Déplacez toutes vos fenêtres d'un coup"
L["WN65_1_TEXT"] = "ClassicUI Forever Windows a un cadre Rangée de fenêtres : faites-le glisser et toutes les fenêtres qui s'ouvrent côte à côte s'y déplacent ensemble."
L["WN65_2_TITLE"] = "Le dressage compte de nouveau en points d'entraînement"
L["WN65_2_TEXT"] = "La fenêtre du dresseur affiche les points d'entraînement de votre familier et ce que coûte chaque technique en points, et Entraîner s'y fie, comme dans Classic Era."

L["WN64_1_TITLE"] = "Estompez vos barres d'action"
L["WN64_1_TEXT"] = "Choisissez une barre en mode Édition : sous les réglages du jeu pour elle, réglez jusqu'où elle s'estompe ou cochez Afficher seulement au survol. Elle redevient pleine sous la souris ou quand vous y faites glisser un sort."
L["WN64_2_TITLE"] = "Erreur des barres de nom corrigée"
L["WN64_2_TEXT"] = "Avec les barres de nom du jeu et les auras d'un autre addon dessus, les nouvelles barres de nom ne causent plus d'erreur Lua."
L["WN64_3_TITLE"] = "Emplacements vides après le grimoire"
L["WN64_3_TEXT"] = "Avec Toujours afficher les boutons désactivé, les emplacements vides de vos barres réapparaissent pour un sort ou un objet pris après avoir fermé le grimoire."
L["WN64_4_TITLE"] = "Corrections de ClassicUI Forever Windows"
L["WN64_4_TEXT"] = "Sa case en mode Édition répond de nouveau aux clics, et la taille de la carte du monde y varie régulièrement à partir de celle de son ouverture."

L["WN63_1_TITLE"] = "Infobulles du butin à côté de l'objet"
L["WN63_1_TEXT"] = "Dans la fenêtre de butin, l'infobulle d'un objet s'ouvre à côté de son icône, comme dans Classic Era, et non plus au-delà du bord droit de la fenêtre."

L["WN62_1_TITLE"] = "Espacez vos barres d'action"
L["WN62_1_TEXT"] = "L'espacement des icônes du mode Édition écarte désormais les boutons de chaque barre d'action. Sur la barre d'action 1, la bande de pierre s'élargit avec lui et chaque bouton reste dans son logement."
L["WN62_2_TITLE"] = "Déballez vos cadeaux dans les Collections"
L["WN62_2_TEXT"] = "Les montures, mascottes et jouets emballés peuvent être déballés dans la fenêtre classique des Collections : choisissez-en un et cliquez sur Déballer, ou cliquez sur un jouet emballé."
L["WN62_3_TITLE"] = "Infobulles comme dans Classic Era"
L["WN62_3_TEXT"] = "Les infobulles de l'apparence classique ont le fond de Classic Era : la même couleur sombre et la même transparence, là où elles étaient plus bleues et plus opaques."

L["WN61_1_TITLE"] = "Questions de taille plus claires"
L["WN61_1_TEXT"] = "Les questions et cases sur la taille de l'interface nomment l'échelle de l'interface du jeu et le pourcentage qu'elles règlent, en moins de mots."
L["WN60_1_TITLE"] = "Cadres de boss classiques"
L["WN60_1_TEXT"] = "Les cadres de boss des combats en donjon et en raid portent l'ancien cadre au dragon, avec le niveau dans son anneau rond et la barre d'incantation à côté ou sous le cadre. Pour retrouver ceux du jeu, décochez Boss dans la liste Cadres des options (/fcui), sous Cadres d'unité."
L["WN60_2_TITLE"] = "Masquer les bordures de qualité"
L["WN60_2_TEXT"] = "Les objets que vous portez sur la fiche de personnage peuvent s'afficher sans la bordure colorée de leur qualité. Désactivé par défaut ; activez-le dans les options (/fcui), sous Fiche de personnage."
L["WN59_1_TITLE"] = "Moins de travail pour le jeu"
L["WN59_1_TEXT"] = "Les barres de nom travaillent beaucoup moins quand vous changez de cible, lancez un sort, gagnez ou perdez des auras, ou êtes entouré d'autres joueurs. Les cadres de cible et de focalisation et la Liste Qui en font aussi moins en arrière-plan."
L["WN58_1_TITLE"] = "Marqueurs de villes d'Era"
L["WN58_1_TEXT"] = "Le Village des Revantusk et le Fort cénarien n'apparaissent sur les cartes des continents qu'une fois leur zone explorée, comme dans Classic Era."
L["WN57_1_TITLE"] = "Afficher les sacs d'un clic"
L["WN57_1_TEXT"] = "Avec Barre des sacs : sac à dos seul, un Ctrl-clic sur le sac à dos affiche les autres sacs ou les replie à nouveau ; la flèche à côté a disparu. Afficher les sacs avec choisit un autre clic. Pour l'activer, choisissez Barre des sacs : sac à dos seul dans les options (/fcui), sous Sacs."
L["WN57_2_TITLE"] = "Masquer les graphismes du trousseau"
L["WN57_2_TEXT"] = "Masquer les graphismes du trousseau libère aussi l'emplacement du trousseau sur la barre classique et remplace Masquer aussi les graphismes du trousseau, en gardant votre choix. Désactivé par défaut ; activez-le dans les options (/fcui), sous Sacs."
L["WN57_3_TITLE"] = "Sacs sans Barre classique"
L["WN57_3_TEXT"] = "Avec Barre classique désactivée, les choix que la barre de sacs du jeu ne peut pas suivre sont grisés, et leur infobulle dit pourquoi."
L["WN56_1_TITLE"] = "Thème personnalisé plus rapide"
L["WN56_1_TEXT"] = "Changer de style ou une partie de Avec thème ne fige plus le jeu, et une partie décochée retrouve les couleurs du jeu. Thème personnalisé est désactivé par défaut ; activez-le dans les options (/fcui), sous Apparence."
L["WN55_1_TITLE"] = "Texture des barres"
L["WN55_1_TEXT"] = "Un choix de Texture des barres dans Cadres d'unité pour les barres de vie et de mana : Classique, désormais plus lisse, Cadres de raid, Unie ou Barre de compétence."
L["WN55_2_TITLE"] = "Bouton de la boutique"
L["WN55_2_TEXT"] = "Le bouton de la boutique peut se placer dans le micro-menu de la 1.x, avec son propre cadre. Il est masqué par défaut : pour l'afficher, décochez Boutique sous Masquer des micro-boutons, dans la page Barres d'action des options (/fcui)."
L["WN55_3_TITLE"] = "Bouton du grimoire"
L["WN55_3_TEXT"] = "Le bouton du grimoire du micro-menu reste enfoncé tant que le grimoire affiche vos sorts."
L["WN55_4_TITLE"] = "Corrections"
L["WN55_4_TEXT"] = "L'infobulle du bouton social indique Social, et un long titre de fenêtre garde les extrémités de sa plaque de titre."
L["WN54_1_TITLE"] = "Options plus fluides"
L["WN54_1_TEXT"] = "Changer une option ne saccade plus : seules les parties de l'interface touchées par cette option sont replacées."
L["WN54_2_TITLE"] = "Micro-menu"
L["WN54_2_TEXT"] = "Les micro-boutons que vous masquez restent masqués, un bouton resté seul sur la rangée se place à son extrémité, et la rangée est centrée sur la barre sans trou dans son fond."
L["WN54_3_TITLE"] = "Minicarte en instance"
L["WN54_3_TEXT"] = "Quand la minicarte tourne, les instances n'affichent plus un second grand anneau autour d'elle."
L["WN54_4_TITLE"] = "Bouton du logis"
L["WN54_4_TEXT"] = "Le bouton du logis du micro-menu a un cadre 1.x comme les autres."
L["WN54_5_TITLE"] = "Corrections"
L["WN54_5_TEXT"] = "Après un rechargement en combat, le cadre de la barre d'expérience du jeu ne s'affiche plus par-dessus celle de 1.x, et une taille de fenêtre enregistrée en mode Édition ne peut plus faire sortir une fenêtre de l'écran, comme une grande carte du monde."
L["WN53_1_TITLE"] = "Parties du thème plus fines"
L["WN53_1_TEXT"] = "Sous Thème personnalisé, la liste Avec thème se divise en parties plus fines, comme les barres d'incantation, les barres de noms, le micro-menu et les menus, pour garder n'importe laquelle avec l'aspect classique. Thème personnalisé est désactivé par défaut ; activez-le dans les options (/fcui), sous Apparence."
L["WN53_2_TITLE"] = "Barres d'action de droite"
L["WN53_2_TEXT"] = "Avec Barre classique désactivée et la minicarte agrandie en mode Édition, les barres d'action 4 et 5 à droite ne rétrécissent plus aux deux tiers environ ; elles rétrécissent seulement autant que l'exige la place sous la minicarte."
L["WN53_3_TITLE"] = "Couleur personnalisée"
L["WN53_3_TEXT"] = "Un clic en dehors du sélecteur de couleur garde la couleur choisie ; Annuler ou Échap l'annule toujours."
L["WN53_4_TITLE"] = "Corrections du thème"
L["WN53_4_TEXT"] = "Quand le thème colore les fenêtres du jeu, elles ne clignotent plus dans leurs propres couleurs à l'ouverture, et les boutons rouges du menu du jeu affichent correctement leurs extrémités. Les cadres des autres addons gardent leur propre aspect ; pour les colorer aussi, activez Autres addons dans la liste Avec thème, dans les options (/fcui), sous Apparence."
L["WN52_1_TITLE"] = "Insigne d'honneur"
L["WN52_1_TEXT"] = "Les cadres du joueur, de la cible et de la focalisation peuvent afficher l'insigne de niveau d'honneur du jeu à la place de l'emblème de faction de la 1.x. Désactivé par défaut ; activez-le dans les options (/fcui), sous Cadres d'unité."
L["WN52_2_TITLE"] = "Onglets du chat au survol"
L["WN52_2_TEXT"] = "Avec les onglets du chat au survol, seuls les onglets de la fenêtre de chat sous la souris s'affichent : ceux des fenêtres ancrées ensemble, ou celui d'une fenêtre sortie à part."
L["WN52_3_TITLE"] = "Œil de la recherche de groupe"
L["WN52_3_TEXT"] = "Aimanter à la minicarte pour l'œil de la recherche de groupe n'est plus dans les options ; il reste dans les réglages de l'œil en mode Édition."
L["WN52_4_TITLE"] = "Œil de la recherche de groupe"
L["WN52_4_TEXT"] = "Aimanter à la minicarte pour l'œil de la recherche de groupe passe des options à son cadre Recherche de groupe dans les fenêtres ClassicUI Forever (mode Édition), sous Minicarte. Le cadre reste tant que l'œil n'est pas sur le bord, pour que vous puissiez le réactiver."
L["WN52_5_TITLE"] = "Infobulle de Flash de dégâts"
L["WN52_5_TEXT"] = "L'infobulle de Flash de dégâts dit que le rouge s'affiche sur la barre de vie du cadre du joueur. Flash de dégâts est désactivé par défaut ; activez-le dans les options (/fcui), sous Cadres d'unité."
L["WN51_1_TITLE"] = "Maîtrise et Polyvalence"
L["WN51_1_TEXT"] = "Les caractéristiques de la fenêtre du personnage montrent Maîtrise et Polyvalence, sous Général."
L["WN51_2_TITLE"] = "Fenêtre des métiers"
L["WN51_2_TEXT"] = "Le choix de l'extension se trouve désormais dans le menu Filtre. La fenêtre s'ouvre là où se tiennent les autres fenêtres du jeu, sans espace après le grimoire, et sa bordure du bas passe sous les boutons Créer."
L["WN51_3_TITLE"] = "Options de Un seul sac"
L["WN51_3_TEXT"] = "Les options sous Un seul sac ne changent que les fenêtres de sac de l'addon, elles sont donc grisées tant que Fenêtres de sac est désactivé. Pour les utiliser, activez-le dans les options (/fcui), sous Sacs."
L["WN51_4_TITLE"] = "Onglets"
L["WN51_4_TEXT"] = "Sur les fenêtres des métiers et des talents, l'onglet choisi montre toute sa face et les autres onglets ne montrent plus de bande noire."
L["WN50_1_TITLE"] = "Couleur texturée"
L["WN50_1_TEXT"] = "Couleur texturée, qui garde la texture de l'art dans la couleur du thème, colore désormais des fenêtres entières, pas seulement leur métal : la pierre des sacs et des onglets, les bords des champs de recherche et de saisie, et les flèches de page du grimoire, une flèche utilisable plus claire qu'une flèche épuisée. Désactivé par défaut ; activez-le dans les options (/fcui), sous Apparence."
L["WN50_2_TITLE"] = "Thèmes sur les fenêtres du jeu"
L["WN50_2_TEXT"] = "Les thèmes colorent aussi l'art du jeu laissé dans les fenêtres que l'addon habille : les onglets de la fenêtre sociale, les barres de défilement, les champs de recherche, les listes déroulantes comme celle du statut, la boîte d'argent, les en-têtes de colonne de la liste de guilde, la boîte de discussion des communautés et l'onglet de raid."
L["WN50_3_TITLE"] = "Bronze sur retail"
L["WN50_3_TEXT"] = "Le thème Bronze colore désormais aussi l'art des fenêtres du jeu, argenté sur retail, comme les autres thèmes."
L["WN50_4_TITLE"] = "Masquer les boutons d'aide"
L["WN50_4_TEXT"] = "Masque les boutons d'aide du jeu, le i en haut à gauche de fenêtres comme la carte, les métiers et le grimoire, et les astuces de tutoriel qu'ils ouvrent. Activé par défaut ; désactivez-le dans les options (/fcui), sous Autre."
L["WN50_5_TITLE"] = "Masquer l'onglet latéral Qui"
L["WN50_5_TEXT"] = "La recherche de groupe peut retirer son onglet latéral Qui, Qui ne s'ouvre alors que depuis la fenêtre sociale. Activé pour les nouvelles installations ; si vous utilisiez déjà l'addon, activez-le dans les options (/fcui), sous Social."
L["WN50_6_TITLE"] = "Corrections"
L["WN50_6_TEXT"] = "L'anneau du portrait du grimoire prend le thème Bronze au lieu de rester argenté, et une flèche de page qui peut de nouveau tourner ne garde plus sa couleur épuisée jusqu'à un clic ailleurs. Les barres de nom montrent le crâne pour les unités amicales de niveau inconnu, comme le cadre de cible. La bordure intérieure des onglets Amis et Raid de la fenêtre sociale prend la couleur du thème, et une erreur que le thème pouvait causer en combat est corrigée."
